import assert from 'node:assert/strict';
import { createHash } from 'node:crypto';
const hash=bytes=>createHash('sha256').update(bytes).digest('hex');
const copy=value=>JSON.parse(JSON.stringify(value));
const target='a'.repeat(64);
const exactAddress='0xfffffffffffffff0';
// Minimal actual NIBArchive bytes: controller, button, view, control connector,
// NSString selector. Encoding follows pinned NibArchive.fixture.ts, not a graph stand-in.
const nibBase64='';
const bytes=Buffer.from(nibBase64,'base64');
const nib={relativePath:'Resources/Main.nib',archiveSHA256:hash(bytes),kind:'nib',format:'nibArchive',bytesBase64:nibBase64};
const jsonDocument=value=>{const bytes=Buffer.from(JSON.stringify(value));return {...nib,relativePath:'Resources/Keyed.nib',format:'keyedArchiveJSON',archiveSHA256:hash(bytes),bytesBase64:bytes.toString('base64')};};
const metadata=()=>({targetSHA256:target,snapshotID:'snapshot-1',value:{db_save_result:null,objc_dispatch_implementations:[{class_name:'BuildViewController',selector:'buildTapped:',method_type:'instance',implementation_address:exactAddress,location:{address:exactAddress,file_offset:null},decode:{status:'decoded',reason:null},evidence:[{kind:'reference',description:'captured method list',location:{address:exactAddress,file_offset:null},artifact_path:null,artifact_sha256:null}]}]}});
export async function run(analyze) {
 let cases=0;
 const call=async(input)=>analyze({operation:'uiResources',input});
 const invoke=async(input)=>{const response=await call(input);if(response.error)throw new Error(JSON.stringify(response.error));return response.result??response;};
 const base={targetSHA256:target,snapshotID:'snapshot-1',documents:[nib],omittedDocuments:0};
 const positive=await invoke({...base,metadata:metadata()});
 assert.ok(positive.analysis.graph.nodes.some(n=>n.kind==='control'));cases++;
 const dispatch=positive.analysis.graph.edges.find(e=>e.relation==='objc_dispatch');
 assert.equal(dispatch.resolution,'resolved');
 assert.equal(dispatch.to,'native:function:'+exactAddress);
 assert.equal(positive.analysis.graph.nodes.find(n=>n.id===dispatch.to).location.address,exactAddress);
 assert.ok(positive.coverage.some(c=>c.reason==='metadata_completeness_unspecified'));cases++;
 assert.ok(positive.analysis.graph.edges.some(e=>e.relation==='contains'),'actual encoded view hierarchy recovered');cases++;
 assert.equal(positive.assetCatalogs,null);
 assert.ok(positive.coverage.some(c=>c.reason==='catalog_metadata_unavailable'));cases++;
 // Actual ibtool-compiled macOS class-swap NIB: custom controller name
 // contains "control", but captured NSOriginalClassName proves its role.
 const swappedBytes=Buffer.from('','base64');
 const swappedMetadata=metadata();
 Object.assign(swappedMetadata.value.objc_dispatch_implementations[0],{class_name:'REAProbeController',selector:'probeTapped:'});
 const swapped=await invoke({...base,documents:[{...nib,archiveSHA256:hash(swappedBytes),bytesBase64:swappedBytes.toString('base64')}],metadata:swappedMetadata});
 assert.ok(swapped.analysis.graph.nodes.some(n=>n.kind==='view_controller'&&n.attributes.class_name==='REAProbeController'));
 assert.equal(swapped.analysis.graph.edges.find(e=>e.relation==='objc_dispatch').to,'native:function:'+exactAddress);cases++;
 const duplicate=metadata();duplicate.value.objc_dispatch_implementations.push({...copy(duplicate.value.objc_dispatch_implementations[0]),class_name:'BuildViewController(Category)'});
 const ambiguous=await invoke({...base,metadata:duplicate});
 assert.equal(ambiguous.dispatchCandidates.length,2);
 assert.equal(ambiguous.analysis.graph.edges.find(e=>e.relation==='objc_dispatch').resolution,'unresolved');
 assert.equal(ambiguous.analysis.graph.edges.find(e=>e.relation==='objc_dispatch').reason,'selector_has_multiple_candidate_implementations');cases++;
 const wrong=metadata();wrong.targetSHA256='b'.repeat(64);
 await assert.rejects(()=>invoke({...base,metadata:wrong}),/wrong image/);cases++;
 const stale=metadata();stale.snapshotID='old';
 await assert.rejects(()=>invoke({...base,metadata:stale}),/snapshot/);cases++;
 const forged=copy(nib);forged.archiveSHA256='0'.repeat(64);
 await assert.rejects(()=>invoke({...base,documents:[forged]}),/hash mismatch/);cases++;
 const malformedBytes=Buffer.from('NIBArchive malformed');
 const malformed={...nib,bytesBase64:malformedBytes.toString('base64'),archiveSHA256:hash(malformedBytes)};
 const partial=await invoke({...base,documents:[malformed],omittedDocuments:2});
 assert.equal(partial.analysis.documents.length,0);
 assert.ok(partial.coverage.some(c=>c.reason==='malformed_or_unsupported_archive'&&c.omitted===1));
 assert.ok(partial.coverage.some(c=>c.facet==='archive_inventory'&&c.status==='partial'&&c.omitted===2));cases++;
 const keyed=jsonDocument({$archiver:'NSKeyedArchiver',$version:100000,$objects:['$null',{$class:{UID:2},title:'Build'},{$classname:'NSButton',$classes:['NSButton','NSControl','NSView','NSObject']}],$top:{root:{UID:1}}});
 const decoded=await invoke({...base,documents:[keyed]});
 assert.ok(decoded.analysis.graph.nodes.some(n=>n.kind==='control'&&n.name==='Build'));cases++;
 const badKeyed=await invoke({...base,documents:[jsonDocument({not:'an archive'})]});
 assert.ok(badKeyed.coverage.some(c=>c.reason==='malformed_or_unsupported_archive'));cases++;
 const rawCatalog=Buffer.from(JSON.stringify([{Name:'BuildIcon',RenditionName:'BuildIcon@2x',Scale:2}]));
 const catalog={path:'Resources/Assets.car',sha256:'c'.repeat(64),captureID:'capture-1',toolSHA256:'d'.repeat(64),metadataSHA256:hash(rawCatalog),metadataJSONBase64:rawCatalog.toString('base64')};
 const assets=await invoke({...base,assetCatalogs:[catalog]});
 assert.equal(assets.assetCatalogs.records[0].asset_name,'BuildIcon');
 assert.equal(assets.assetCatalogs.records[0].metadata.Scale,2);
 assert.equal(assets.catalogProvenance[0].captureID,'capture-1');cases++;
 const omittedCatalogs=await invoke({...base,assetCatalogs:[catalog],omittedCatalogs:3});
 assert.equal(omittedCatalogs.assetCatalogs.records[0].asset_name,'BuildIcon');
 assert.ok(omittedCatalogs.coverage.some(c=>c.facet==='asset_catalog_inventory'&&c.status==='partial'&&c.examined===1&&c.omitted===3));cases++;
 const noCapturedCatalogs=await invoke({...base,omittedCatalogs:5});
 assert.ok(noCapturedCatalogs.coverage.some(c=>c.facet==='asset_catalog_inventory'&&c.omitted===5));cases++;
 await assert.rejects(()=>invoke({...base,omittedCatalogs:-1}));cases++;
 const emptyCatalogs=await invoke({...base,assetCatalogs:[]});
 assert.ok(emptyCatalogs.coverage.some(c=>c.reason==='no_captured_catalog_metadata'));cases++;
 const malformedCatalog=copy(catalog);const malformedJSON=Buffer.from('{}');malformedCatalog.metadataJSONBase64=malformedJSON.toString('base64');malformedCatalog.metadataSHA256=hash(malformedJSON);
 assert.ok((await invoke({...base,assetCatalogs:[malformedCatalog]})).coverage.some(c=>c.reason==='malformed_catalog_metadata'));cases++;
 await assert.rejects(()=>invoke({...base,documents:[nib,nib]}),/duplicate archive/);cases++;
 await assert.rejects(()=>invoke({...base,documents:[{...nib,relativePath:'../Main.nib'}]}),/root-relative/);cases++;
 const numeric=metadata();numeric.value.objc_dispatch_implementations[0].implementation_address=Number.MAX_SAFE_INTEGER+1;
 await assert.rejects(()=>invoke({...base,metadata:numeric}),/unsafe integer|string/);cases++;
 const large=jsonDocument({$archiver:'NSKeyedArchiver',$objects:['$null','x'.repeat(6*1024*1024)],$top:{root:{UID:1}}});
 const exhausted=await call({...base,documents:[large]});
 assert.equal(exhausted.ok,false);
 assert.match(JSON.stringify(exhausted.error),/budget/);cases++;
 return {cases,status:'passed'};
}
